    {"id": "kh4_20", "level": 4, "term": "신사임당", "definition": "율곡 이이의 어머니이자 초충도, 산수화, 시문에 뛰어난 예술적 업적을 남긴 여류 화가."},
    {"id": "kh4_21", "level": 4, "term": "율곡이이", "definition": "동호문답, 격몽요결을 짓고 기호학파의 거두로서 10만 양병설을 주장한 성리학자."},
    {"id": "kh4_22", "level": 4, "term": "퇴계이황", "definition": "성학십도와 주자서절요를 저술하고 영남학파의 영수가 되어 일본 성리학에도 큰 영향을 줌."},
    {"id": "kh4_23", "level": 4, "term": "송시열", "definition": "효종과 함께 북벌론을 추진하고 노론의 영수로서 조선 후기 정계를 호령한 유학자."},
    {"id": "kh4_24", "level": 4, "term": "허균", "definition": "신분 차별의 부당함을 고발하고 부패한 사회를 개혁하려는 최초의 한글 소설 홍길동전을 씀."},
    {"id": "kh4_25", "level": 4, "term": "홍길동전", "definition": "적서차별에 분노한 홍길동이 활빈당을 이끌고 탐관오리를 응징한 최초의 국문 영웅 소설."},
    {"id": "kh4_26", "level": 4, "term": "춘향전", "definition": "신분을 초월한 이몽룡과 성춘향의 지고지순한 사랑과 변학도의 탐욕을 통쾌하게 응징함."},
    {"id": "kh4_27", "level": 4, "term": "구운몽", "definition": "김만중이 유배지에서 어머니를 위로하기 위해 인간 세상의 부귀영화가 일장춘몽임을 그린 소설."},
    {"id": "kh4_28", "level": 4, "term": "허준", "definition": "선조의 어의로서 15년간 각고의 노력 끝에 향약과 침구술을 집대성한 동의보감을 완성함."},
    {"id": "kh4_29", "level": 4, "term": "장영실", "definition": "동래현 관노 출신이었으나 세종대왕의 발탁으로 자격루와 측우기, 혼천의를 제작한 과학자."},
    {"id": "kh4_30", "level": 4, "term": "박연", "definition": "세종대왕을 도와 아악을 정리하고 편경과 편종을 만들어 국악의 음률 체계를 정립한 음악가."},
    {"id": "kh4_31", "level": 4, "term": "맹사성", "definition": "황희 정승과 함께 세종대를 보좌하며 검소하고 청백리로서 백성의 존경을 받은 명재상."},

    # Lv.5 (+21)
    {"id": "kh5_11", "level": 5, "term": "흥선대원군", "definition": "어린 고종을 대신해 섭정하며 서원 철폐, 쇄국 정책, 경복궁 중건을 단행한 인물."},
    {"id": "kh5_12", "level": 5, "term": "척화비", "definition": "병인양요와 신미양요를 겪은 후 전국 요충지에 세워 서양 오랑캐와의 화친을 거부한 비석."},
    {"id": "kh5_13", "level": 5, "term": "경복궁중건", "definition": "임진왜란 때 불탄 경복궁을 흥선대원군이 왕실의 위엄을 되살리기 위해 거대하게 재건함."},
    {"id": "kh5_14", "level": 5, "term": "당백전", "definition": "경복궁 중건 비용을 마련하기 위해 상평통보 액면가의 100배 가치로 발행해 물가를 폭등시킨 화폐."},
    {"id": "kh5_15", "level": 5, "term": "서원철폐", "definition": "백성을 수탈하고 붕당의 근거지가 된 전국의 서원을 47개소만 남기고 과감히 철폐함."},
    {"id": "kh5_16", "level": 5, "term": "호포제", "definition": "양반에게도 평민과 똑같이 군포를 징수하여 신분 차별을 없애고 국가 재정을 확충함."},
    {"id": "kh5_17", "level": 5, "term": "사창제", "definition": "환곡의 폐단을 바로잡기 위해 관청 대신 마을 자치적으로 곡식을 빌려주고 갚게 한 제도."},
    {"id": "kh5_18", "level": 5, "term": "병인양요", "definition": "1866년 프랑스 함대가 병인박해를 구실로 강화도를 침략했으나 양헌수 부대 등이 격퇴함."},
    {"id": "kh5_19", "level": 5, "term": "신미양요", "definition": "1871년 미국 아시아함대가 제너럴셔먼호 사건을 구실로 강화도 광성보를 침략한 사건."},
    {"id": "kh5_20", "level": 5, "term": "어재연", "definition": "신미양요 때 강화도 광성보에서 미군에 맞서 수자기 깃발 아래 결사항전 끝에 장렬히 전사한 장수."},
    {"id": "kh5_21", "level": 5, "term": "강화도조약", "definition": "1876년 운요호 사건을 계기로 일본과 체결한 우리나라 최초의 불평등 근대적 조약."},
    {"id": "kh5_22", "level": 5, "term": "조미수호통상", "definition": "1882년 청나라의 알선으로 서양 국가 중 최초로 미국과 체결한 수호통상조약."},
    {"id": "kh5_23", "level": 5, "term": "통리기무아문", "definition": "개항 이후 근대적 개화 정책과 군사·통상 사무를 총괄하기 위해 설치한 최고 행정 관청."},
    {"id": "kh5_24", "level": 5, "term": "별기군", "definition": "일본인 교관을 초빙하여 신식 무기와 군사 훈련을 받게 한 조선 최초의 근대식 신식 군대."},
    {"id": "kh5_25", "level": 5, "term": "임오군란", "definition": "1882년 13개월간 급료를 받지 못하고 차별 대우를 받던 구식 군인들이 일으킨 봉기."},
    {"id": "kh5_26", "level": 5, "term": "제물포조약", "definition": "임오군란으로 일본 공사관이 불탄 것에 대해 일본에 배상금을 지불하고 공사관 경비병 주둔을 허용함."},
    {"id": "kh5_27", "level": 5, "term": "갑신정변", "definition": "1884년 김옥균, 박영효 등 급진개화파가 우정총국 개국 축하연을 기회로 일으킨 3일 천하 정변."},
    {"id": "kh5_28", "level": 5, "term": "우정총국", "definition": "홍영식을 총판으로 하여 근대식 우편 사무를 처리하기 위해 설립된 최초의 우체국."},
    {"id": "kh5_29", "level": 5, "term": "한성순보", "definition": "박문국에서 열흘마다 발행한 우리나라 최초의 근대식 순한문 관보 신문."},
    {"id": "kh5_30", "level": 5, "term": "독립문", "definition": "독립협회가 청나라 사신을 맞던 영은문을 헐고 자주독립의 의지를 다지기 위해 세운 서양식 석문."},
    {"id": "kh5_31", "level": 5, "term": "독립협회", "definition": "서재필, 윤치호 등이 중심이 되어 독립신문을 발간하고 만민공동회를 주최한 애국 계몽 단체."},

    # Lv.6 (+21)
    {"id": "kh6_11", "level": 6, "term": "전봉준", "definition": "고부 군수 조병갑의 탐학에 맞서 농민들을 이끌고 봉기한 동학농민운동의 최고 지도자."},
    {"id": "kh6_12", "level": 6, "term": "녹두장군", "definition": "키가 작지만 다부지고 결단력이 뛰어났던 동학농민군 지도자 전봉준을 백성들이 부른 애칭."},
    {"id": "kh6_13", "level": 6, "term": "고부봉기", "definition": "만석보를 쌓아 가혹한 수세를 징수한 탐관오리 조병갑에 저항하여 농민들이 관아를 습격함."},
    {"id": "kh6_14", "level": 6, "term": "사발통문", "definition": "주모자가 드러나지 않도록 사발을 엎어놓고 둥글게 둘러가며 이름을 서명한 비밀 격문."},
    {"id": "kh6_15", "level": 6, "term": "백산봉기", "definition": "동학농민군이 백산에 집결하여 '앉으면 백산, 서면 죽산'의 기세로 제폭구민, 보국안민을 선포함."},
    {"id": "kh6_16", "level": 6, "term": "황토현전투", "definition": "1894년 동학농민군이 전라감영 관군을 황토현에서 야간 기습으로 대파한 최초의 대승."},
    {"id": "kh6_17", "level": 6, "term": "황룡촌전투", "definition": "장성 황룡촌에서 장태(닭장)를 굴리는 전법으로 관군의 신식 대포 공격을 무력화하고 승리함."},
    {"id": "kh6_18", "level": 6, "term": "전주화약", "definition": "농민군이 전주성을 점령하자 청일 양국 군대의 개입을 우려해 정부와 농민군이 맺은 평화 협약."},
    {"id": "kh6_19", "level": 6, "term": "집강소", "definition": "전주화약 이후 전라도 53개 군현에 설치된 농민 자치 행정 기구로 폐정 개혁을 단행함."},
    {"id": "kh6_20", "level": 6, "term": "폐정개혁안", "definition": "동학농민군이 신분제 폐지, 토지 균등 분배, 탐관오리 처벌 등을 요구한 12개 조의 개혁안."},
    {"id": "kh6_21", "level": 6, "term": "우금치전투", "definition": "공주 우금치 고개에서 농민군이 일본군의 기관총 화력에 맞서 결사 돌격했으나 참패한 전투."},
    {"id": "kh6_22", "level": 6, "term": "갑오개혁", "definition": "군국기무처를 설치하여 신분제 철폐, 과거제 폐지, 과부 재가 허용 등 근대적 제도를 단행함."},
    {"id": "kh6_23", "level": 6, "term": "군국기무처", "definition": "제1차 갑오개혁을 총괄 주도한 초정부적 근대 개혁 추진 기구."},
    {"id": "kh6_24", "level": 6, "term": "홍범십사조", "definition": "고종이 종묘에 나아가 자주독립과 근대 국가 개혁의 기본 강령을 선포한 14개 조항의 법률."},
    {"id": "kh6_25", "level": 6, "term": "을미사변", "definition": "1895년 일본 공사 미우라의 지휘 아래 일본 낭인들이 경복궁을 침범해 명성황후를 시해한 만행."},
    {"id": "kh6_26", "level": 6, "term": "단발령", "definition": "을미개혁 때 위생과 편리함을 내세워 성인 남자의 상투를 강제로 자르게 한 명령."},
    {"id": "kh6_27", "level": 6, "term": "을미의병", "definition": "명성황후 시해와 단발령에 분노한 유생과 백성들이 '신체발부 수지부모'를 외치며 일으킨 의병."},
    {"id": "kh6_28", "level": 6, "term": "아관파천", "definition": "1896년 신변에 위협을 느낀 고종이 경복궁을 빠져나와 러시아 공사관으로 거처를 옮긴 사건."},
    {"id": "kh6_29", "level": 6, "term": "대한제국", "definition": "1897년 고종이 러시아 공사관에서 환궁한 후 황제 즉위식을 올리고 선포한 자주독립 제국."},
    {"id": "kh6_30", "level": 6, "term": "광무개혁", "definition": "구본신참의 원칙 아래 양전 사업, 지계 발급, 상공업 진흥 및 근대 기술 교육을 추진한 개혁."},
    {"id": "kh6_31", "level": 6, "term": "환구단", "definition": "고종 황제가 하늘에 제사를 지내고 대한제국 황제 즉위식을 거행하기 위해 세운 제천 제단."},

    # Lv.7 (+21)
    {"id": "kh7_11", "level": 7, "term": "을사늑약", "definition": "1905년 일본이 군대를 동원해 강압적으로 체결하여 대한제국의 외교권을 강탈한 불법 조약."},
    {"id": "kh7_12", "level": 7, "term": "을사오적", "definition": "을사늑약 체결에 적극 찬동하고 서명한 매국노 이완용, 이근택, 이지용, 박제순, 권중현."},
    {"id": "kh7_13", "level": 7, "term": "시일야방성대곡", "definition": "장지연이 황성신문에 실어 을사늑약의 불법성과 민족의 비통함을 통곡하며 규탄한 논설."},
    {"id": "kh7_14", "level": 7, "term": "민영환", "definition": "을사늑약 체결에 통분하여 2천만 동포에게 각성을 촉구하는 유서를 남기고 자결 순국한 애국지사."},
    {"id": "kh7_15", "level": 7, "term": "헤이그특사", "definition": "1907년 네덜란드 헤이그 만국평화회의에 이상설, 이준, 이위종을 파견해 늑약의 무효를 폭로함."},
    {"id": "kh7_16", "level": 7, "term": "이준열사", "definition": "헤이그 만국평화회의에서 각국 대표의 외면으로 뜻을 이루지 못하자 현지에서 순국한 열사."},
    {"id": "kh7_17", "level": 7, "term": "정미의병", "definition": "1907년 군대 해산에 분노한 해산 군인들이 합류하여 무기와 조직력을 갖추고 전개한 전국 의병."},
    {"id": "kh7_18", "level": 7, "term": "군대해산", "definition": "일제가 고종을 강제 퇴위시킨 후 정미7조약을 맺고 대한제국 군대를 강제로 해산시킨 사건."},
    {"id": "kh7_19", "level": 7, "term": "안중근", "definition": "1909년 10월 26일 하얼빈역에서 침략의 원흉 이토 히로부미를 권총으로 저격 처단한 의사."},
    {"id": "kh7_20", "level": 7, "term": "하얼빈의거", "definition": "안중근 의사가 러시아 하얼빈역 플랫폼에서 대한독립 만세를 외치며 이토를 사살한 쾌거."},
    {"id": "kh7_21", "level": 7, "term": "동양평화론", "definition": "안중근 의사가 뤼순 감옥에서 한중일 삼국이 협력해 서구 제국주의에 맞서야 한다고 저술한 책."},
    {"id": "kh7_22", "level": 7, "term": "신민회", "definition": "안창호, 양기탁 등이 결성하여 공화정 수립을 목표로 신흥무관학교를 세운 비밀결사 단체."},
    {"id": "kh7_23", "level": 7, "term": "양기탁", "definition": "영국인 베델과 함께 대한매일신보를 창간하여 일제의 침략을 맹렬히 비판한 독립운동가."},
    {"id": "kh7_24", "level": 7, "term": "신채호", "definition": "'역사는 아와 비아의 투쟁'이라 규정하고 조선상고사와 조선혁명선언을 집필한 민족주의 사학자."},
    {"id": "kh7_25", "level": 7, "term": "박은식", "definition": "일제 침략의 만행을 기록한 한국통사와 한국독립운동지혈사를 저술한 임시정부 제2대 대통령."},
    {"id": "kh7_26", "level": 7, "term": "국채보상운동", "definition": "1907년 대구에서 서상돈 등의 제안으로 국민이 담배를 끊고 패물을 모아 일본 빚 1300만원을 갚으려 함."},
    {"id": "kh7_27", "level": 7, "term": "서상돈", "definition": "대구 광문사 부사장을 지내며 국채보상운동의 불씨를 지핀 애국 계몽 운동가."},
    {"id": "kh7_28", "level": 7, "term": "대종교", "definition": "나철이 단군 신앙을 부활하여 만주 일대 무장 독립운동의 사상적 기반을 제공한 민족 종교."},
    {"id": "kh7_29", "level": 7, "term": "보안회", "definition": "1904년 일제가 황무지 개척권을 강탈하려 하자 범국민적 반대 투쟁을 벌여 철회시킨 단체."},
    {"id": "kh7_30", "level": 7, "term": "헌정연구회", "definition": "입헌군주제 도입을 목표로 의회 설립 운동과 정치 개혁을 추진한 애국 계몽 단체."},
    {"id": "kh7_31", "level": 7, "term": "대한자강회", "definition": "교육과 식산흥업을 통해 국력을 기르고자 월보를 발간하며 고종 퇴위 반대 운동을 이끈 단체."},

    # Lv.8 (+21)
    {"id": "kh8_11", "level": 8, "term": "기미독립선언", "definition": "1919년 3월 1일 태화관에서 낭독된 '우리는 오늘 조선이 독립한 나라이며 자주민임을 선언하노라'는 명문."},
    {"id": "kh8_12", "level": 8, "term": "민족대표", "definition": "손병희, 한용운, 이승훈 등 3·1 만세운동의 독립선언서에 서명한 33인의 종교계 지도자."},
    {"id": "kh8_13", "level": 8, "term": "유관순", "definition": "이화학당 학생으로 천안 아우내장터에서 태극기를 나누어주며 만세 시위를 주도한 애국 열사."},
    {"id": "kh8_14", "level": 8, "term": "아우내장터", "definition": "1919년 4월 1일 유관순 열사의 주도로 수천 명의 군중이 대한독립 만세를 외친 역사적 현장."},
    {"id": "kh8_15", "level": 8, "term": "제암리교회", "definition": "3·1 만세운동에 보복하기 위해 일본 군경이 주민들을 교회에 가두고 불태워 학살한 참변."},
    {"id": "kh8_16", "level": 8, "term": "상하이임정", "definition": "3·1 운동의 결실로 연해주, 서울 등의 정부를 통합하여 중국 상하이에 수립된 통합임시정부."},
    {"id": "kh8_17", "level": 8, "term": "김구", "definition": "한인애국단을 조직하고 한국광복군을 창설하며 대한민국임시정부 주석으로 독립을 이끈 지도자."},
    {"id": "kh8_18", "level": 8, "term": "안창호", "definition": "신민회와 흥사단을 창립하고 점진적 인격 수양과 민족의 실력 양성을 평생 역설한 지도자."},
    {"id": "kh8_19", "level": 8, "term": "이동녕", "definition": "임시의정원 초대의장을 지내고 임시정부의 정신적 지주로서 수차례 주석을 맡은 원로 애국지사."},
    {"id": "kh8_20", "level": 8, "term": "구미위원부", "definition": "이승만을 중심으로 미국 워싱턴에 설치되어 미국 정계와 언론을 상대로 독립 외교를 펼친 기구."},
    {"id": "kh8_21", "level": 8, "term": "파리강화회의", "definition": "신한청년당이 김규식을 대표로 파견하여 윌슨의 민족자결주의에 입각해 한국의 독립을 청원함."},
    {"id": "kh8_22", "level": 8, "term": "김규식", "definition": "파리강화회의 대표 파견, 임시정부 부주석, 해방 후 좌우합작운동을 이끈 독립운동가이자 정치가."},
    {"id": "kh8_23", "level": 8, "term": "연통제", "definition": "임시정부가 국내외를 연결하여 군자금을 모으고 명령을 하달하기 위해 구축한 비밀 지하 행정망."},
    {"id": "kh8_24", "level": 8, "term": "독립공채", "definition": "임시정부가 독립운동 자금을 조달하기 위해 훗날 국권 회복 시 원금과 이자를 갚기로 하고 발행한 채권."},
    {"id": "kh8_25", "level": 8, "term": "백범일지", "definition": "백범 김구가 두 아들에게 남긴 유서이자 상하이와 중경 임시정부의 투쟁사를 생생히 담은 자서전."},
    {"id": "kh8_26", "level": 8, "term": "백산상회", "definition": "안희제 등이 부산에 설립하여 무역 회사로 위장하고 임시정부에 거액의 독립 자금을 댄 비밀 거점."},
    {"id": "kh8_27", "level": 8, "term": "의열단", "definition": "1919년 만주 길림에서 김원봉 등이 조직하여 일제의 주요 요인 암살과 식민지 기관 파괴를 벌인 단체."},
    {"id": "kh8_28", "level": 8, "term": "김원봉", "definition": "의열단 단장으로서 조선혁명간부학교를 설립하고 민족혁명당과 조선의용대를 이끈 항일 투사."},
    {"id": "kh8_29", "level": 8, "term": "조선혁명선언", "definition": "신채호가 의열단의 행동 강령으로 작성하여 민중의 직접 폭력 혁명만이 진정한 자유를 얻는다고 천명함."},
    {"id": "kh8_30", "level": 8, "term": "나석주", "definition": "의열단 단원으로 식민지 수탈의 총본산인 동양척식주식회사와 식산은행에 폭탄을 투척하고 자결함."},
    {"id": "kh8_31", "level": 8, "term": "신간회", "definition": "1927년 비타협적 민족주의 세력과 사회주의 세력이 손을 잡고 결성한 일제강점기 최대 민족유일당."},

    # Lv.9 (+21)
    {"id": "kh9_11", "level": 9, "term": "봉오동전투", "definition": "1920년 6월 홍범도의 대한독립군 연합부대가 일본군 월강추격대를 골짜기로 유인해 섬멸한 대승."},
    {"id": "kh9_12", "level": 9, "term": "홍범도", "definition": "봉오동 전투와 청산리 대첩을 승리로 이끈 전설적인 포수 출신의 항일 독립군 총사령관."},
    {"id": "kh9_13", "level": 9, "term": "청산리대첩", "definition": "1920년 10월 김좌진의 북로군정서와 홍범도 부대가 백운평, 어랑촌 등에서 일본군 대부대를 대파함."},
    {"id": "kh9_14", "level": 9, "term": "김좌진", "definition": "사관연성소를 통해 정예 독립군을 양성하고 청산리 대첩을 진두지휘한 백야 장군."},
    {"id": "kh9_15", "level": 9, "term": "북로군정서", "definition": "대종교 신자들을 중심으로 만주 북간도에 조직되어 뛰어난 무장력으로 청산리 대첩을 이끈 군대."},
    {"id": "kh9_16", "level": 9, "term": "대한독립군", "definition": "홍범도 장군이 만주에서 창설하여 두만강을 건너 국내 진공 작전을 활발히 펼친 독립군 부대."},
    {"id": "kh9_17", "level": 9, "term": "간도참변", "definition": "봉오동과 청산리에서 패배한 일제가 보복으로 간도 일대의 무고한 한인 마을과 민간인을 대량 학살함."},
    {"id": "kh9_18", "level": 9, "term": "자유시참변", "definition": "러시아 연해주 자유시로 집결한 한인 무장독립군이 지휘권 갈등과 소련 붉은군대의 무장 해제로 희생당함."},
    {"id": "kh9_19", "level": 9, "term": "참의부", "definition": "압록강 연안에서 임시정부 직속 육군주만참의부로 활동하며 국경 지대 유격전을 펼친 자치 정부."},
    {"id": "kh9_20", "level": 9, "term": "정의부", "definition": "길림과 봉천 일대 남만주 동포 사회를 이끌며 양기탁, 지청천 등이 참여한 자치 독립운동 정부."},
    {"id": "kh9_21", "level": 9, "term": "신민부", "definition": "김좌진을 중심으로 북만주 밀산 일대 독립군과 동포들을 통합하여 세운 무장 자치 단체."},
    {"id": "kh9_22", "level": 9, "term": "한인애국단", "definition": "1931년 임시정부의 침체를 타개하기 위해 김구가 상하이에서 결성한 특무 암살 공작 조직."},
    {"id": "kh9_23", "level": 9, "term": "윤봉길", "definition": "1932년 상하이 훙커우공원 일본군 전승기념식 단상에 도시락과 물통 폭탄을 던져 군 수뇌부를 도륙함."},
    {"id": "kh9_24", "level": 9, "term": "훙커우의거", "definition": "윤봉길 의사의 폭탄 거사로 중국 장제스가 '중국의 1억 군대도 못한 일을 한 청년이 해냈다'며 임정을 전폭 지원함."},
    {"id": "kh9_25", "level": 9, "term": "이봉창", "definition": "도쿄 사쿠라다몬 앞에서 일본 천황 히로히토의 마차 행렬을 향해 수류탄을 던진 애국 열사."},
    {"id": "kh9_26", "level": 9, "term": "한국광복군", "definition": "1940년 충칭에서 대한민국임시정부의 정규 군대로 창설되어 대일 선전포고와 국내 진공 작전을 준비함."},
    {"id": "kh9_27", "level": 9, "term": "지청천", "definition": "신흥무관학교 교장을 거쳐 한국독립당 군사위원장이자 한국광복군 총사령관을 지낸 장군."},
    {"id": "kh9_28", "level": 9, "term": "조선어학회", "definition": "우리말 사전 편찬과 한글맞춤법 통일안을 제정하다 일제에 의해 집단 투옥된 학술 독립운동 단체."},
    {"id": "kh9_29", "level": 9, "term": "맞춤법통일안", "definition": "1933년 조선어학회가 표준어 사정안과 함께 제정하여 현대 한글 표기법의 절대적 표준이 된 규정."},
    {"id": "kh9_30", "level": 9, "term": "이육사", "definition": "의열단에 가담해 무장투쟁을 벌이며 '광야', '청포도' 등 강철 같은 저항시를 남긴 시인이자 투사."},
    {"id": "kh9_31", "level": 9, "term": "윤동주", "definition": "후쿠오카 형무소에서 옥사하기까지 '서시', '별 헤는 밤'을 통해 부끄러움과 조국 독립을 노래한 민족 시인."},

    # Lv.10 (+21)
    {"id": "kh10_11", "level": 10, "term": "카이로회담", "definition": "1943년 미국, 영국, 중국 3국 정상이 모여 '한국인의 노예 상태에 유의하여 적절한 시기에 독립시킬 것'을 최초 보장함."},
    {"id": "kh10_12", "level": 10, "term": "포츠담선언", "definition": "1945년 미·영·중·소 연합국이 일본의 무조건 항복을 촉구하며 카이로 회담의 조항을 재확인함."},
    {"id": "kh10_13", "level": 10, "term": "건국준비위", "definition": "8·15 광복 직후 여운형, 안재홍 등이 중심이 되어 치안 유지와 자주 국가 건설을 위해 조직한 위원회."},
    {"id": "kh10_14", "level": 10, "term": "여운형", "definition": "조선건국동맹과 건국준비위원회를 이끌고 좌우합작운동을 추진하며 통일 정부 수립에 헌신한 지도자."},
    {"id": "kh10_15", "level": 10, "term": "모스크바삼상", "definition": "1945년 12월 미·영·소 3국 외무장관이 모여 한반도 임시민주정부 수립과 최대 5년 신탁통치를 결정함."},
    {"id": "kh10_16", "level": 10, "term": "신탁통치논쟁", "definition": "모스크바 회담 결정 이후 찬탁을 주장하는 좌익과 반탁을 외치는 우익 간의 극심한 이념 대립."},
    {"id": "kh10_17", "level": 10, "term": "좌우합작", "definition": "김규식과 여운형이 주도하여 신탁통치 논쟁으로 갈라진 민족을 하나로 묶고 통일 임시정부를 세우려 함."},
    {"id": "kh10_18", "level": 10, "term": "남북협상", "definition": "1948년 김구와 김규식이 단독 정부 수립에 반대하며 평양으로 건너가 남북 연석회의를 연 역사적 담판."},
    {"id": "kh10_19", "level": 10, "term": "제헌국회", "definition": "1948년 5·10 총선거를 통해 선출되어 대한민국 최초의 헌법을 제정하고 공포한 역사적 의회."},
    {"id": "kh10_20", "level": 10, "term": "오일공총선", "definition": "1948년 5월 10일 유엔 감시하에 38선 이남 지역에서 실시된 우리나라 최초의 보통·평등 근대 선거."},
    {"id": "kh10_21", "level": 10, "term": "대한민국정부", "definition": "1948년 8월 15일 이승만을 초대 대통령으로 하여 공식 출범한 한반도의 유일한 합법 정부."},
    {"id": "kh10_22", "level": 10, "term": "육이오전쟁", "definition": "1950년 6월 25일 새벽 북한군의 기습 남침으로 시작되어 수백만 명의 사상자와 분단을 남긴 동족상잔의 비극."},
    {"id": "kh10_23", "level": 10, "term": "인천상륙작전", "definition": "맥아더 장군의 지휘 아래 조수간만의 차를 극복하고 인천에 기습 상륙해 서울을 탈환하고 전세를 뒤집음."},
